cat > /tmp/test_cycles.js << 'EOF'
import { addMonths } from './src/dates.js';

const CYCLE = Object.freeze({ MONTH: 'monthly', YEAR: 'yearly' });
const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };

export function nextCharge(sub, today) {
  const step = MONTHS_PER_CHARGE[sub.cycle];
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}

const sub1 = { cycle: 'monthly', since: '2026-09-02' };
const sub2 = { cycle: 'monthly', since: '2026-09-30' };

console.log('Gym next charge from 2026-10-25:', nextCharge(sub1, '2026-10-25'));
console.log('Music next charge from 2026-10-25:', nextCharge(sub2, '2026-10-25'));
EOF
node /tmp/test_cycles.js

